// Secure token-based session management with ring buffer for audit log
namespace session_mgr {

static constexpr size_t AUDIT_BUFFER_SIZE = 64;
static constexpr size_t MAX_TOKEN_LEN = 128;
static constexpr size_t HMAC_LEN = 32;

struct AuditEntry {
    uint32_t timestamp;
    uint32_t user_id;
    char action[56];
};

static_assert(sizeof(AuditEntry) == 64, "AuditEntry must be 64 bytes");

// ---------------------------------------------------------------------------
// Portable SHA-256 implementation (public-domain style) used to build a proper
// HMAC-SHA256. This replaces the previous homemade XOR-based MAC (CWE-327).
// ---------------------------------------------------------------------------
namespace crypto {

struct Sha256 {
    uint32_t h[8];
    uint64_t total_len;
    uint8_t buffer[64];
    size_t buffer_len;

    static uint32_t rotr(uint32_t x, uint32_t n) { return (x >> n) | (x << (32 - n)); }

    void init() {
        h[0] = 0x6a09e667; h[1] = 0xbb67ae85; h[2] = 0x3c6ef372; h[3] = 0xa54ff53a;
        h[4] = 0x510e527f; h[5] = 0x9b05688c; h[6] = 0x1f83d9ab; h[7] = 0x5be0cd19;
        total_len = 0;
        buffer_len = 0;
    }

    void process_block(const uint8_t* p) {
        static const uint32_t k[64] = {
            0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
            0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
            0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
            0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
            0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
            0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
            0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
            0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
        };
        uint32_t w[64];
        for (int i = 0; i < 16; i++) {
            w[i] = (uint32_t(p[i * 4]) << 24) | (uint32_t(p[i * 4 + 1]) << 16) |
                   (uint32_t(p[i * 4 + 2]) << 8) | (uint32_t(p[i * 4 + 3]));
        }
        for (int i = 16; i < 64; i++) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; i++) {
            uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            uint32_t ch = (e & f) ^ (~e & g);
            uint32_t t1 = hh + S1 + ch + k[i] + w[i];
            uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    void update(const uint8_t* data, size_t len) {
        total_len += len;
        while (len > 0) {
            size_t to_copy = std::min(len, size_t(64) - buffer_len);
            std::memcpy(buffer + buffer_len, data, to_copy);
            buffer_len += to_copy;
            data += to_copy;
            len -= to_copy;
            if (buffer_len == 64) {
                process_block(buffer);
                buffer_len = 0;
            }
        }
    }

    void finish(uint8_t out[32]) {
        uint64_t bit_len = total_len * 8;
        uint8_t pad = 0x80;
        update(&pad, 1);
        uint8_t zero = 0x00;
        while (buffer_len != 56) {
            update(&zero, 1);
        }
        uint8_t len_be[8];
        for (int i = 0; i < 8; i++) {
            len_be[7 - i] = uint8_t(bit_len >> (i * 8));
        }
        update(len_be, 8);
        for (int i = 0; i < 8; i++) {
            out[i * 4]     = uint8_t(h[i] >> 24);
            out[i * 4 + 1] = uint8_t(h[i] >> 16);
            out[i * 4 + 2] = uint8_t(h[i] >> 8);
            out[i * 4 + 3] = uint8_t(h[i]);
        }
    }
};

inline void sha256(const uint8_t* data, size_t len, uint8_t out[32]) {
    Sha256 ctx;
    ctx.init();
    ctx.update(data, len);
    ctx.finish(out);
}

// HMAC-SHA256
inline std::array<uint8_t, 32> hmac_sha256(const uint8_t* key, size_t key_len,
                                           const uint8_t* data, size_t data_len) {
    uint8_t k_block[64];
    std::memset(k_block, 0, sizeof(k_block));
    if (key_len > 64) {
        uint8_t hashed_key[32];
        sha256(key, key_len, hashed_key);
        std::memcpy(k_block, hashed_key, 32);
    } else {
        std::memcpy(k_block, key, key_len);
    }

    uint8_t ipad[64], opad[64];
    for (int i = 0; i < 64; i++) {
        ipad[i] = k_block[i] ^ 0x36;
        opad[i] = k_block[i] ^ 0x5c;
    }

    Sha256 inner;
    inner.init();
    inner.update(ipad, 64);
    inner.update(data, data_len);
    uint8_t inner_hash[32];
    inner.finish(inner_hash);

    Sha256 outer;
    outer.init();
    outer.update(opad, 64);
    outer.update(inner_hash, 32);
    std::array<uint8_t, 32> mac{};
    outer.finish(mac.data());
    return mac;
}

